<?php
include('../auth/check.php');
include('../config/db.php');
$sql="SELECT q.id,q.queue_number,q.queue_type,q.workflow_status,q.counter_number,q.table_number,b.first_name,b.middle_name,b.last_name,b.ext_name,b.barangay,b.lgu,e.form_locked,e.eligibility_status,e.approved_cash_amount FROM queue_entries q JOIN beneficiaries b ON b.id=q.beneficiary_id LEFT JOIN eligibility_forms e ON e.queue_entry_id=q.id WHERE DATE(q.transaction_date)=CURDATE() AND q.workflow_status IN ('WAITING_STEP_3','CALLED_STEP_3','HELD') ORDER BY CASE WHEN q.workflow_status='CALLED_STEP_3' THEN 0 WHEN q.queue_type='priority' THEN 1 ELSE 2 END,q.id ASC";
$result=$conn->query($sql);
function h($v){return htmlspecialchars($v??'',ENT_QUOTES,'UTF-8');}
function fnm($r){return trim($r['last_name'].', '.$r['first_name'].' '.$r['middle_name'].' '.$r['ext_name']);}
function counterDropdown($name='counter_number',$selected=1){$selected=intval($selected ?: 1);$html='<select class="counter-select" name="'.$name.'" title="Counter">';for($i=1;$i<=10;$i++){$sel=$i===$selected?' selected':'';$html.='<option value="'.$i.'"'.$sel.'>Counter '.$i.'</option>';}$html.='</select>';return $html;}
?>
<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Confirmation</title><link rel="stylesheet" href="../assets/style.css"><link href="https://fonts.googleapis.com/icon?family=Material+Icons" rel="stylesheet"><style>.content{overflow:auto}.head{background:linear-gradient(135deg,#16a34a,#0f766e);color:white;padding:22px;margin:-22px -22px 18px}.head h1{margin:0}.toolbar{display:grid;grid-template-columns:1fr 150px 170px 120px;gap:10px;margin-bottom:12px;align-items:center}.toolbar input,.toolbar select{height:42px;padding:0 12px;border:1px solid #cbd5e1;border-radius:8px;background:#fff}.card{background:white;border:1px solid #d6dce8;border-radius:12px;overflow:hidden;display:flex;flex-direction:column;max-height:calc(100vh - 190px)}.table-scroll{overflow:auto;flex:1;min-height:0}.tbl{width:100%;border-collapse:collapse;table-layout:fixed;min-width:1080px}.tbl th,.tbl td{padding:12px 14px;border-bottom:1px solid #e5e7eb;text-align:left;white-space:nowrap;vertical-align:middle}.tbl th{background:#f8fafc;font-size:12px;text-transform:uppercase;position:sticky;top:0;z-index:2}.tbl th:nth-child(1),.tbl td:nth-child(1){width:12%}.tbl th:nth-child(2),.tbl td:nth-child(2){width:23%}.tbl th:nth-child(3),.tbl td:nth-child(3){width:19%}.tbl th:nth-child(4),.tbl td:nth-child(4){width:14%}.tbl th:nth-child(5),.tbl td:nth-child(5){width:16%}.tbl th:nth-child(6),.tbl td:nth-child(6){width:16%}.prio td{background:#fff7ed}.held td{background:#fef2f2}.qprio{color:#c2410c;font-weight:900}.badge{padding:5px 9px;border-radius:999px;background:#e5e7eb;font-size:11px;font-weight:900}.counter-chip{display:inline-block;margin-top:5px;color:#0f766e;font-weight:900;font-size:12px}.amt{font-weight:900;color:#166534}.actions{display:flex;gap:8px;align-items:center;justify-content:flex-start}.actions form{margin:0;display:inline-flex;gap:8px;align-items:center}.counter-select{height:38px;width:112px;border:1px solid #cbd5e1;border-radius:8px;background:white;font-size:12px;font-weight:900;color:#111827;padding:0 6px}.ib{width:38px;height:38px;border:0;border-radius:8px;color:white;display:inline-flex;align-items:center;justify-content:center;text-decoration:none;cursor:pointer}.ib span{font-size:20px}.call{background:#10b981}.paid{background:#16a34a}.cancel{background:#ef4444}.off{opacity:.35;pointer-events:none}.pager{display:flex;align-items:center;justify-content:center;gap:8px;padding:12px;border-top:1px solid #e5e7eb;background:#fff;flex-shrink:0}.pg{height:34px;min-width:34px;border:1px solid #cbd5e1;background:white;border-radius:7px;padding:7px 10px;cursor:pointer;font-weight:800}.pg:disabled{opacity:.45;cursor:not-allowed}.page-info{font-size:13px;color:#475569;font-weight:800}@media(max-width:900px){.toolbar{grid-template-columns:1fr 1fr}.card{max-height:none}.tbl{min-width:1080px}}</style></head><body><div class="app"><main class="main"><section class="content"><div class="head"><h1>Confirmation / Payout [Step 3]</h1><p>Call assessed beneficiaries, choose counter, and mark payout as paid.</p></div><div class="toolbar"><input id="s" placeholder="Search"><select id="t"><option value="">All Types</option><option value="priority">PRIO</option><option value="regular">PAL</option></select><select id="st"><option value="">All Status</option><option value="WAITING_STEP_3">Waiting</option><option value="CALLED_STEP_3">Called</option><option value="HELD">Held</option></select><select id="rowsPerPage"><option value="10">10 rows</option><option value="25" selected>25 rows</option><option value="50">50 rows</option><option value="100">100 rows</option></select></div><div class="card"><div class="table-scroll"><table class="tbl"><thead><tr><th>Queue</th><th>Name</th><th>Barangay/LGU</th><th>Amount</th><th>Status</th><th>Actions</th></tr></thead><tbody id="rows">
<?php if($result): while($r=$result->fetch_assoc()): $isPrio=$r['queue_type']==='priority'; $isHeld=$r['workflow_status']==='HELD'; $isCalled=$r['workflow_status']==='CALLED_STEP_3'; $isWaiting=$r['workflow_status']==='WAITING_STEP_3'; $counter=intval($r['counter_number'] ?: $r['table_number'] ?: 1); $gis=intval($r['form_locked']??0)===1 && ($r['eligibility_status']??'')==='Eligible' && floatval($r['approved_cash_amount']??0)>0; ?>
<tr class="data <?php echo $isHeld?'held':($isPrio?'prio':''); ?>" data-type="<?php echo h($r['queue_type']); ?>" data-status="<?php echo h($r['workflow_status']); ?>"><td class="<?php echo $isPrio?'qprio':''; ?>"><?php echo h($r['queue_number']); ?></td><td><?php echo h(fnm($r)); ?></td><td><?php echo h($r['barangay']); ?>/<?php echo h($r['lgu']); ?></td><td class="amt"><?php echo $gis?'₱'.number_format(floatval($r['approved_cash_amount']),2):'No amount'; ?></td><td><span class="badge"><?php echo h($r['workflow_status']); ?></span><?php if($isCalled): ?><br><span class="counter-chip">Counter <?php echo $counter; ?></span><?php endif; ?></td><td><div class="actions">
<?php if($isWaiting): ?>
<form method="POST" action="../api/call_queue.php"><input type="hidden" name="queue_id" value="<?php echo intval($r['id']); ?>"><?php echo counterDropdown('counter_number',1); ?><input type="hidden" name="redirect" value="../staff/confirmation_screen.php"><button class="ib call" title="Call"><span class="material-icons">campaign</span></button></form>
<form method="POST" action="../api/cancel_queue.php"><input type="hidden" name="queue_id" value="<?php echo intval($r['id']); ?>"><input type="hidden" name="redirect" value="../staff/confirmation_screen.php"><button class="ib cancel" title="Cancel"><span class="material-icons">close</span></button></form>
<?php elseif($isCalled): ?>
<form method="POST" action="../api/mark_paid.php"><input type="hidden" name="queue_id" value="<?php echo intval($r['id']); ?>"><input type="hidden" name="counter_number" value="<?php echo $counter; ?>"><input type="hidden" name="redirect" value="../staff/confirmation_screen.php"><button class="ib paid <?php echo !$gis?'off':''; ?>" title="Paid"><span class="material-icons">payments</span></button></form>
<form method="POST" action="../api/cancel_queue.php"><input type="hidden" name="queue_id" value="<?php echo intval($r['id']); ?>"><input type="hidden" name="redirect" value="../staff/confirmation_screen.php"><button class="ib cancel" title="Cancel"><span class="material-icons">close</span></button></form>
<?php else: ?>
<form method="POST" action="../api/cancel_queue.php"><input type="hidden" name="queue_id" value="<?php echo intval($r['id']); ?>"><input type="hidden" name="redirect" value="../staff/confirmation_screen.php"><button class="ib cancel" title="Cancel"><span class="material-icons">close</span></button></form>
<?php endif; ?>
</div></td></tr>
<?php endwhile; endif; ?>
</tbody></table></div><div class="pager" id="p"></div></div></section></main><?php include('sidebar.php'); ?></div><script>const rows=[...document.querySelectorAll('.data')],s=document.getElementById('s'),t=document.getElementById('t'),st=document.getElementById('st'),rpp=document.getElementById('rowsPerPage'),p=document.getElementById('p');let page=1;function filteredRows(){let a=s.value.toLowerCase(),ty=t.value,sta=st.value;return rows.filter(r=>(!ty||r.dataset.type===ty)&&(!sta||r.dataset.status===sta)&&r.innerText.toLowerCase().includes(a))}function apply(){let vis=filteredRows(),per=parseInt(rpp.value,10),pages=Math.max(1,Math.ceil(vis.length/per));if(page>pages)page=pages;rows.forEach(r=>r.style.display='none');vis.slice((page-1)*per,page*per).forEach(r=>r.style.display='');p.innerHTML=`<button class="pg" ${page===1?'disabled':''} onclick="page=1;apply()">«</button><button class="pg" ${page===1?'disabled':''} onclick="page--;apply()">‹</button><span class="page-info">Page ${page} of ${pages}</span><button class="pg" ${page===pages?'disabled':''} onclick="page++;apply()">›</button><button class="pg" ${page===pages?'disabled':''} onclick="page=${pages};apply()">»</button>`}[s,t,st,rpp].forEach(e=>{e.addEventListener('input',()=>{page=1;apply()});e.addEventListener('change',()=>{page=1;apply()})});apply();</script></body></html>